insert into public.content_item_categories(item_id,game_id,category_id,sort_order,enabled) select item_id,'choose-your-side',category_id,sort_order,true from decked_choose_side_v1_active on conflict(item_id,game_id,category_id) do update set sort_order=excluded.sort_order,enabled=true;
insert into public.content_item_versions(item_id,version,body,normalized_body,metadata,editorial_status,change_note) select item_id,next_version,body,lower(regexp_replace(body,'[^[:alnum:]'']+',' ','g')),metadata,'published','Choose Your Side playable V1 editorial revision' from decked_choose_side_v1_revisions on conflict(item_id,version) do update set body=excluded.body,normalized_body=excluded.normalized_body,metadata=excluded.metadata,editorial_status='published',change_note=excluded.change_note;
insert into public.content_releases(id,game_id,status,item_count,membership_count,checksum,notes,published_at) values('78bc4e2a-50ce-5a9c-a9ee-0290faf06b08'::uuid,'choose-your-side','published',250,250,'ca9cceb473ab91e42d076c48bc2684aa2f4225c50aae9ec1497e01ee937c0138','Choose Your Side playable V1; all 300 historical identities preserved.',now()) on conflict(id) do update set status='published',item_count=250,membership_count=250,checksum=excluded.checksum,notes=excluded.notes,published_at=now();
insert into public.content_release_items(release_id,item_id,version,category_ids) select '78bc4e2a-50ce-5a9c-a9ee-0290faf06b08'::uuid,item.id,item.published_version,array[selected.category_id] from decked_choose_side_v1_active selected join public.content_items item on item.id=selected.item_id where item.game_id='choose-your-side' and item.published_version is not null;
