-- Recovered from the linked project's Supabase migration history.

-- Choose Your Side playable V1: 250 active choices, 50 preserved archived choices.
begin;

create temporary table decked_choose_side_v1_active(item_id uuid primary key,category_id text not null,sort_order integer not null,body text not null,metadata jsonb not null,revised boolean not null) on commit drop;


do $$ declare matched integer; begin select count(*) into matched from public.content_items item join decked_choose_side_v1_active selected on selected.item_id=item.id where item.game_id='choose-your-side'; if matched<>250 then raise exception 'Choose Your Side V1 inventory mismatch: expected 250 IDs, found %',matched; end if; end $$;

update public.content_items set lifecycle_status='archived',updated_at=now() where game_id='choose-your-side';

update public.content_items item set lifecycle_status='active',updated_at=now() from decked_choose_side_v1_active selected where item.id=selected.item_id and item.game_id='choose-your-side';

update public.content_item_categories set enabled=false where game_id='choose-your-side';


create temporary table decked_choose_side_v1_revisions on commit drop as select selected.*,item.current_version+1 next_version from decked_choose_side_v1_active selected join public.content_items item on item.id=selected.item_id where selected.revised;

update public.content_item_versions version set editorial_status='superseded' from decked_choose_side_v1_revisions revised where version.item_id=revised.item_id and version.version=(select published_version from public.content_items where id=revised.item_id);


update public.content_items item set current_version=revised.next_version,published_version=revised.next_version,updated_at=now() from decked_choose_side_v1_revisions revised where item.id=revised.item_id;

update public.content_item_versions version set metadata=coalesce(version.metadata,'{}'::jsonb)||selected.metadata from decked_choose_side_v1_active selected join public.content_items item on item.id=selected.item_id where not selected.revised and version.item_id=item.id and version.version=item.published_version;

update public.content_releases set status='superseded' where game_id='choose-your-side' and status='published';


delete from public.content_release_items where release_id='78bc4e2a-50ce-5a9c-a9ee-0290faf06b08'::uuid;


commit;
